def transform(grid):
    divider = next(r for r, row in enumerate(grid) if all(v == 5 for v in row))
    top, bottom = grid[:divider], grid[divider + 1:]

    def count(region, color):
        return sum(cell == color for row in region for cell in row)

    growth2 = count(bottom, 2) - count(top, 2)
    growth4 = count(bottom, 4) - count(top, 4)
    if growth2 == growth4:
        color = 2 if count([*top, *bottom], 2) > count([*top, *bottom], 4) else 4
    else:
        color = 2 if growth2 > growth4 else 4
    return [[color, color], [color, color]]
